-- Executar no SQLcl/SQL*Plus conectado ao banco do catalogo tdcsp.
-- Nao executado. Destino: schema existente AGENT_SEARCH.
-- Se a tabela ja existir, interrompe sem substituir seus dados.
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
CREATE TABLE AGENT_SEARCH.TDC_DC_PAGAMENTOS (
 tentativa_id VARCHAR2(30) PRIMARY KEY, pedido_id VARCHAR2(30) NOT NULL,
 dia DATE NOT NULL, horario VARCHAR2(8) NOT NULL, metodo VARCHAR2(10) NOT NULL,
 status VARCHAR2(20) NOT NULL, valor NUMBER(12,2) NOT NULL,
 canal VARCHAR2(10) NOT NULL, codigo_erro VARCHAR2(60),
 CONSTRAINT TDC_DC_METODO_CK CHECK (metodo IN ('cartao','pix'))
);
-- Oracle confirma DDL implicitamente; em falha posterior pode restar a tabela vazia.
BEGIN
END;
/
DECLARE
 n NUMBER;
BEGIN
 SELECT COUNT(*) INTO n FROM AGENT_SEARCH.TDC_DC_PAGAMENTOS;
 IF n <> 2000 THEN RAISE_APPLICATION_ERROR(-20001, 'Contagem diferente de 2000'); END IF;
 SELECT COUNT(*) INTO n FROM (
  SELECT dia, metodo, COUNT(*) tentativas,
   SUM(CASE WHEN status = 'aprovado' THEN 1 ELSE 0 END) aprovados,
   SUM(CASE WHEN status = 'aprovado' THEN valor ELSE 0 END) receita
  FROM AGENT_SEARCH.TDC_DC_PAGAMENTOS GROUP BY dia, metodo
 ) WHERE
 (dia=DATE '2026-09-19' AND metodo='cartao' AND tentativas=600 AND aprovados=540 AND receita=54000) OR
 (dia=DATE '2026-09-20' AND metodo='cartao' AND tentativas=600 AND aprovados=270 AND receita=27000) OR
 (dia=DATE '2026-09-19' AND metodo='pix' AND tentativas=400 AND aprovados=360 AND receita=36000) OR
 (dia=DATE '2026-09-20' AND metodo='pix' AND tentativas=400 AND aprovados=360 AND receita=36000);
 IF n <> 4 THEN RAISE_APPLICATION_ERROR(-20002, 'Totais divergentes do caso Aurora'); END IF;
END;
/
COMMIT;
SELECT dia, metodo, COUNT(*) tentativas,
 SUM(CASE WHEN status = 'aprovado' THEN 1 ELSE 0 END) aprovados,
 SUM(CASE WHEN status = 'aprovado' THEN valor ELSE 0 END) receita
FROM AGENT_SEARCH.TDC_DC_PAGAMENTOS GROUP BY dia, metodo ORDER BY dia, metodo;
